property.value:
let $iterations := ('forEach', 'forEachOrdered', 'map', 'flatMap', 'peek', 'mapToObj'),
    $passes := function($node) {
      $node/ancestor::*[self::ForeachStatement or self::ForStatement or self::WhileStatement or self::DoStatement
        or self::LambdaExpression[parent::ArgumentList/parent::MethodCall[@MethodName = $iterations][*[1][pmd-java:typeIs('java.util.stream.BaseStream') or pmd-java:typeIs('java.lang.Iterable')
          or pmd-java:typeIs('java.util.Map') or pmd-java:typeIs('java.util.Iterator')]]]]
    },
    $collectionValued := function($target, $outer) {
      let $name := $target/@Name,
          $scope := $target/ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration or self::LambdaExpression][last()],
          $declarations := ($scope//LocalVariableDeclaration[VariableDeclarator/VariableId/@Name = $name]
            | $scope//FormalParameter[VariableId/@Name = $name]
            | $target/ancestor::ClassBody[1]/FieldDeclaration[VariableDeclarator/VariableId/@Name = $name])
            [empty(ancestor::* intersect $outer)]
      return exists($declarations[1]/ClassType[pmd-java:typeIs('java.util.Map')]/TypeArguments/*[2]
        [pmd-java:typeIs('java.util.Collection') or pmd-java:typeIs('java.util.Map')])
    }
return
//MethodCall[@MethodName = 'putAll'][ArgumentList/@Size = 1][*[1][self::VariableAccess or self::FieldAccess]]
  [let $outer := $passes(.)[last()],
       $elements := ($outer/self::ForeachStatement/LocalVariableDeclaration | $outer/self::LambdaExpression/LambdaParameterList)
         //VariableId/@Name
   return exists($outer) and $collectionValued(*[1], $outer)
     and (exists(ArgumentList/*[1][self::VariableAccess][@Name = $elements])
       or exists($outer/self::LambdaExpression/parent::ArgumentList/parent::MethodCall
         /*[1]/descendant-or-self::MethodCall[@MethodName = ('parallelStream', 'parallel')]))]
|
//MethodCall[@MethodName = 'put'][ArgumentList/@Size = 2][*[1][self::VariableAccess or self::FieldAccess]]
  [let $value := ArgumentList/*[2],
       $entryLoop := ancestor::ForeachStatement[*[2][self::MethodCall][@MethodName = 'entrySet']]
         [LocalVariableDeclaration//VariableId/@Name = $value[self::MethodCall][@MethodName = 'getValue']
           /*[1][self::VariableAccess]/@Name][1],
       $entryLambda := ancestor::LambdaExpression[parent::ArgumentList/parent::MethodCall[@MethodName = 'forEach']
           [*[1][pmd-java:typeIs('java.util.Map')]]]
         [LambdaParameterList/*[2]//VariableId/@Name = $value[self::VariableAccess]/@Name][1],
       $inner := ($entryLoop | $entryLambda)[1],
       $outer := $passes($inner)[last()],
       $target := *[1]/@Name
   return exists($inner) and exists($outer) and $collectionValued(*[1], $outer)
     and exists(ArgumentList/*[1][self::VariableAccess or self::MethodCall[@MethodName = 'getKey'][ArgumentList/@Size = 0]])
     and empty(ancestor::IfStatement[ancestor::* intersect $inner]/*[1]//MethodCall
       [@MethodName = ('containsKey', 'get', 'isEmpty')][*[1][self::VariableAccess or self::FieldAccess][@Name = $target]])]
